CREATE TABLE IF NOT EXISTS roster_scopes (school_id TEXT NOT NULL, scope TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(school_id,scope));
CREATE TABLE IF NOT EXISTS roster_records (school_id TEXT NOT NULL, collection TEXT NOT NULL, record_id TEXT NOT NULL, service_date TEXT, staff_id TEXT, year TEXT, revision INTEGER NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(school_id,collection,record_id));
CREATE INDEX IF NOT EXISTS roster_records_date ON roster_records(school_id,service_date,collection);
CREATE INDEX IF NOT EXISTS roster_records_staff ON roster_records(school_id,staff_id,service_date);
CREATE INDEX IF NOT EXISTS roster_records_year ON roster_records(school_id,year,collection);
CREATE TABLE IF NOT EXISTS roster_baselines (school_id TEXT NOT NULL, baseline_id TEXT NOT NULL, revision INTEGER NOT NULL, name TEXT NOT NULL, from_date TEXT NOT NULL, to_date TEXT NOT NULL, priority INTEGER NOT NULL, model_key TEXT NOT NULL, digest TEXT NOT NULL, mapping_json TEXT NOT NULL, venue_mapping_json TEXT NOT NULL DEFAULT '{}', pruned INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(school_id,baseline_id));
CREATE INDEX IF NOT EXISTS roster_baselines_dates ON roster_baselines(school_id,from_date,to_date,pruned);
CREATE TABLE IF NOT EXISTS roster_runs (school_id TEXT NOT NULL, run_id TEXT NOT NULL, operation_id TEXT NOT NULL, service_date TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','yielded','committed','conflicted','cancelled','failed')), fence INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL, snapshot_json TEXT NOT NULL, proposal_json TEXT, progress_json TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(school_id,run_id));
CREATE INDEX IF NOT EXISTS roster_runs_state ON roster_runs(school_id,state,updated_at);
CREATE TABLE IF NOT EXISTS roster_weekly (school_id TEXT NOT NULL, staff_id TEXT NOT NULL, week TEXT NOT NULL, publication_id TEXT NOT NULL, publication_sequence INTEGER NOT NULL, calculation_version TEXT NOT NULL, quota REAL NOT NULL, excluded INTEGER NOT NULL DEFAULT 0, exclusion_reason TEXT NOT NULL DEFAULT '', captured_at INTEGER NOT NULL, evidence_json TEXT NOT NULL, PRIMARY KEY(school_id,staff_id,week));
CREATE TABLE IF NOT EXISTS roster_ledger (school_id TEXT NOT NULL, duty_id TEXT NOT NULL, correction_revision INTEGER NOT NULL, staff_id TEXT NOT NULL, service_date TEXT NOT NULL, period INTEGER, period_count INTEGER NOT NULL, charge REAL NOT NULL, completion_basis TEXT NOT NULL, assignment_json TEXT NOT NULL, actor_id TEXT NOT NULL, reason TEXT NOT NULL, operation_id TEXT NOT NULL, recorded_at INTEGER NOT NULL, PRIMARY KEY(school_id,duty_id,correction_revision));
CREATE INDEX IF NOT EXISTS roster_ledger_range ON roster_ledger(school_id,service_date,staff_id);
CREATE TABLE IF NOT EXISTS roster_openings (school_id TEXT NOT NULL, staff_id TEXT NOT NULL, year TEXT NOT NULL, revision INTEGER NOT NULL, cutoff TEXT NOT NULL, period_count INTEGER, charge REAL NOT NULL, source_digest TEXT NOT NULL, operation_id TEXT NOT NULL, PRIMARY KEY(school_id,staff_id,year));
CREATE TABLE IF NOT EXISTS roster_publications (school_id TEXT NOT NULL, publication_id TEXT NOT NULL, service_date TEXT NOT NULL, sequence INTEGER NOT NULL, operation_id TEXT NOT NULL, source_digest TEXT NOT NULL, payload_key TEXT NOT NULL, payload_json TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(school_id,publication_id), UNIQUE(school_id,service_date,sequence));
CREATE TABLE IF NOT EXISTS roster_leases (school_id TEXT NOT NULL, service_date TEXT NOT NULL, actor_id TEXT NOT NULL, fence INTEGER NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(school_id,service_date));
CREATE TABLE IF NOT EXISTS roster_schedule (school_id TEXT NOT NULL, slot_key TEXT NOT NULL, service_date TEXT NOT NULL, outcome TEXT NOT NULL, operation_id TEXT NOT NULL, recorded_at INTEGER NOT NULL, PRIMARY KEY(school_id,slot_key));
CREATE TABLE IF NOT EXISTS roster_inbox (school_id TEXT NOT NULL, message_id TEXT NOT NULL, staff_id TEXT, received_at INTEGER NOT NULL, state TEXT NOT NULL, assigned_to TEXT, revision INTEGER NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(school_id,message_id));
CREATE INDEX IF NOT EXISTS roster_inbox_state ON roster_inbox(school_id,state,received_at);
CREATE TABLE IF NOT EXISTS roster_prepared_publications (school_id TEXT NOT NULL, operation_id TEXT NOT NULL, digest TEXT NOT NULL, fence INTEGER NOT NULL, projection_json TEXT NOT NULL, venue_proof_json TEXT, PRIMARY KEY(school_id,operation_id));
CREATE TABLE IF NOT EXISTS roster_deploy_adoption (school_id TEXT PRIMARY KEY, publication_id TEXT NOT NULL, sequence INTEGER NOT NULL, payload_json TEXT NOT NULL, adopted_at INTEGER NOT NULL, operation_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roster_exports (school_id TEXT NOT NULL, export_id TEXT NOT NULL, publication_id TEXT NOT NULL, digest TEXT NOT NULL, artifact_key TEXT NOT NULL, created_at INTEGER NOT NULL, provider_file_id TEXT, last_success_at INTEGER, PRIMARY KEY(school_id,export_id));
CREATE TABLE IF NOT EXISTS roster_provider_events (school_id TEXT NOT NULL, event_id TEXT NOT NULL, provider TEXT NOT NULL, provider_message_id TEXT NOT NULL, event_kind TEXT NOT NULL, event_at INTEGER NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(school_id,event_id));

CREATE TABLE IF NOT EXISTS roster_duties (school_id TEXT NOT NULL, duty_id TEXT NOT NULL, service_date TEXT NOT NULL, end_at INTEGER NOT NULL, publication_id TEXT NOT NULL, publication_sequence INTEGER NOT NULL, payload_json TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(school_id,duty_id));
CREATE INDEX IF NOT EXISTS roster_duties_due ON roster_duties(school_id,completed,end_at);

CREATE TABLE IF NOT EXISTS roster_projection_chunks (school_id TEXT NOT NULL, operation_id TEXT NOT NULL, chunk_index INTEGER NOT NULL, chunk_digest TEXT NOT NULL, artifact_key TEXT NOT NULL, row_count INTEGER NOT NULL, PRIMARY KEY(school_id,operation_id,chunk_index));
CREATE TABLE IF NOT EXISTS roster_external_links (school_id TEXT NOT NULL, token_hash TEXT NOT NULL, job_id TEXT NOT NULL, staff_id TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN ('mutual','duties')), service_date TEXT NOT NULL, source_revision TEXT NOT NULL, expires_at INTEGER NOT NULL, capability_json TEXT NOT NULL, token_cipher TEXT NOT NULL, owner_operation_id TEXT NOT NULL, consumed_operation_id TEXT, PRIMARY KEY(school_id,token_hash), UNIQUE(school_id,job_id));
CREATE TABLE IF NOT EXISTS roster_external_commands (school_id TEXT NOT NULL, operation_id TEXT NOT NULL, token_hash TEXT NOT NULL, command_digest TEXT NOT NULL, command_json TEXT NOT NULL, PRIMARY KEY(school_id,operation_id));
CREATE TABLE IF NOT EXISTS roster_drive_exports (school_id TEXT NOT NULL, publication_id TEXT NOT NULL, file_id TEXT NOT NULL, content_digest TEXT NOT NULL, folder_id TEXT NOT NULL, state TEXT NOT NULL, last_error TEXT, last_success_at INTEGER, updated_at INTEGER NOT NULL, PRIMARY KEY(school_id,publication_id));
